const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=[],selected=null,current=null,history=[],local=[],counts=[],filter='all';
const cache=new Map();
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()};}
async function manifest(id){if(cache.has(id))return cache.get(id);const r=await api('catalog/'+encodeURIComponent(id));if(r.ok){cache.set(id,r.data);return r.data;}if(r.status===404){const e=entries.find(e=>e.id===id);return e?{...e,replay:{status:e.replay_status},unavailable:true}:null;}throw new Error(r.data.detail||'The proof package could not load.');}
function groups(e){const g={};for(const f of e.closure||[]){const p=f.path.split('/');const dir=p.length>2?p.slice(0,2).join('/')+'/':p.length>1?p[0]+'/':'Bundle root';(g[dir]??=[]).push(f);}return Object.entries(g);}
function graph(e,r={}){if(r.kind==='miss')return `<p class="graph-label">No matching proof path</p><div class="node dangling"><small>Dangling demand / no matched entry</small><strong>${esc(r.key)}</strong></div><p class="graph-label">Logged as demand. No proof or checker was selected by this lookup.</p>`;if(!e)return '<p>The proof package is unavailable. Select another library entry.</p>';const hit=r.kind==='lookup',check=r.kind==='check',lit=hit?' lit':'';return `<p class="graph-label">${hit?'Matched proof path':check?'Touched checker and its proof context':'Selected proof path'} / connections name dependencies, not proof steps</p><div class="flow"><div class="node${lit}"><small>Entry</small><strong>${esc(e.id)}</strong>${check?`<div class="node check-node lit"><small>Input checker</small><strong>${esc(r.verdict)}</strong></div>`:''}</div><div class="node${lit}"><small>Subject / artifact</small><strong>${esc(e.subject?.name||e.title)}</strong>${e.subject?.artifact?`<small>${esc(e.subject.artifact.name)}<br>${esc(e.subject.artifact.bytes)} bytes</small>`:''}</div><div class="node${lit}"><small>Delivered closure</small>${e.unavailable?'Manifest unavailable':`<details><summary><strong>${e.closure.length} files in ${groups(e).length} groups</strong></summary>${groups(e).map(([dir,files])=>`<details><summary>${esc(dir)} (${files.length})</summary>${files.map(f=>`<p>${esc(f.path)}</p>`).join('')}</details>`).join('')}</details>`}</div><div class="node${lit}"><small>Required libraries + toolchain</small>${(e.requires||[]).map(x=>`<span>${esc(x)}</span>`).join('')}<span>${esc(e.toolchain)}</span></div></div><details class="graph-text"><summary>Read the proof path as text</summary><ul><li>Entry: ${esc(e.id)}</li><li>Subject: ${esc(e.subject?.name)}${e.subject?.artifact?` / artifact ${esc(e.subject.artifact.name)} / SHA-256 ${esc(e.subject.artifact.sha256)}`:''}</li><li>Closure: ${e.closure?.length??'unavailable'} files${groups(e).map(([dir,files])=>`<ul><li>${esc(dir)}: ${files.length} files</li></ul>`).join('')}</li><li>Libraries: ${esc((e.requires||[]).join(', ')||'None listed')}</li><li>Toolchain: ${esc(e.toolchain)}</li>${check?`<li>Checker verdict: ${esc(r.verdict)}</li>`:''}</ul></details>`;}
function evidence(e,open=false){if(!e)return '';if(e.unavailable)return `<p class="notice"><strong>Recorded stub. Not re-run by fvapi.</strong><br>The full manifest is unavailable in this mock. Choose another entry to inspect delivered files.</p><p>${esc(e.claim)}</p>`;return `<details class="evidence" ${open?'open':''}><summary>Inspect proof package / ${esc(e.title)}</summary><p>${esc(e.claim)}</p>${e.replay.status==='recorded'?'<p class="notice"><strong>Recorded replay. Not re-run by fvapi.</strong><br>This transcript comes from an earlier run. It does not establish a fresh replay on this service.</p>':'<p>Real replay available. Re-run the bundle to establish the result yourself.</p>'}<div class="evidence-grid"><div><h3>Statements to match</h3>${e.statements.map(s=>`<p><code>${esc(s.name)}<br>${esc(s.file)}:${esc(s.line)}</code></p><pre>${esc(s.text)}</pre>`).join('')}<h3>Closure files and SHA-256</h3><div class="files">${groups(e).map(([dir,files])=>`<details><summary>${esc(dir)} / ${files.length} files</summary>${files.map(f=>`<div class="file"><strong>${esc(f.path)}</strong><br>${f.bytes} bytes<code>${esc(f.sha256)}</code></div>`).join('')}</details>`).join('')}</div></div><div><h3>Replay on your machine</h3><pre>${esc(e.replay.command)}</pre><button data-copy="${esc(e.id)}">Copy replay command</button> <a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download bundle</a><p>${esc(e.replay.note)}</p><dl><dt>Expected axioms</dt><dd>${esc(e.replay.expect_axioms.join(', ')||'None')}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>'):'No third-party notices in this manifest.'}</dd><dt>Source repository</dt><dd>${esc(e.source.repo)}</dd><dt>Source commit</dt><dd><code>${esc(e.source.commit)}</code></dd><dt>Source paths</dt><dd>${e.source.paths.map(esc).join('<br>')}</dd></dl>${e.replay.transcript?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}</div></div></details>`;}
function stamp(at){if(!at)return 'Selected';const date=new Date(at);return Number.isNaN(+date)?esc(at):`${date.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}<br>${date.toLocaleDateString([], {month:'short',day:'numeric'})}`;}
function expanded(r,open=false){const negative=['reject','No match','No checker','Input error','Error'].includes(r.verdict);return `<div class="readout ${negative?'negative':''}"><div class="verdict"><small>${r.kind==='selected'?'Proof package':r.kind==='lookup'?'Lookup result':r.kind==='miss'?'Lookup result':'Checker output'}</small>${esc(r.verdict)}</div><div class="reason"><p>${esc(r.reason)}</p><small>${esc(r.metrics||'Read the statement and re-check the delivered proof yourself.')}</small></div></div>${graph(r.entry,r)}${r.result?`<details class="graph-text"><summary>Read the full response and local re-check instructions</summary><pre>${esc(JSON.stringify(r.result,null,2))}</pre></details>`:''}${evidence(r.entry,open)}`;}
function renderCurrent(open=false){$('#current').innerHTML=`<div class="stamp">${stamp(current.at)}<span class="dot"></span></div><div class="row-body"><div class="row-title"><h2>${current.kind==='selected'?'Selected proof package':current.kind==='miss'?'Unmatched lookup':current.kind==='check'?'Input check':'Specification lookup'}</h2><small>${esc(current.key||current.entry?.id||'')}</small></div>${expanded(current,open)}</div>`;}
function renderCatalog(){ $('#catalog').innerHTML=entries.map(e=>`<button type="button" data-entry="${esc(e.id)}" aria-pressed="${selected?.id===e.id}"><b>${esc(e.subject?.name||e.title)}</b><small>${esc(e.id)} / ${esc(e.replay_status)}</small></button>`).join('');}
async function select(id,open=false){if(current&&current.kind!=='selected')local.unshift(current);const e=await manifest(id);if(!e)throw new Error('This entry is unavailable. Choose another entry.');selected=e;$('#input').value=JSON.stringify(e.check?.example_input||{},null,2);$('#input-note').textContent=e.check?'Edit the JSON, then run the check.':'This entry has no checker. A check returns 409.';renderCatalog();current={kind:'selected',entry:e,verdict:e.replay.status==='recorded'?'Recorded':'Ready',reason:e.replay.status==='recorded'?'Not re-run by fvapi. Inspect the earlier transcript and replay it yourself.':'Proof package selected. No input check has been submitted.'};renderCurrent(open);renderHistory();}
async function loadLogs(){const [a,d]=await Promise.all([api('answers'),api('demand')]);if(!a.ok||!d.ok)throw new Error('The request logs could not load. Reload to try again.');history=[...a.data.answers.map(x=>({...x,kind:x.kind,verdict:x.verdict||'Found',key:x.entry_id})),...d.data.misses.map(x=>({...x,kind:'miss',verdict:'No match',key:JSON.stringify(x.query)}))].sort((a,b)=>String(b.at).localeCompare(String(a.at)));counts=d.data.by_key||[];renderHistory();}
function renderHistory(){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));$('#counts').innerHTML=filter==='demand'?`<div class="counts"><strong>Demand counts by key</strong>${counts.length?counts.map(x=>`<p><code>${esc(x.key)}</code> / ${x.count} requests</p>`).join(''):'<p>No misses recorded. Look up a specification to create a request.</p>'}</div>`:'';const seen=new Set([...local,current].filter(Boolean).map(r=>r.result?.answer_id||r.result?.miss_id).filter(Boolean));const rows=[...local,...history.filter(r=>!seen.has(r.answer_id||r.miss_id))].filter(r=>filter==='all'||(filter==='demand'?r.kind==='miss':r.kind!=='miss'));$('#records').innerHTML=rows.length?rows.map((r,i)=>`<div class="row"><div class="stamp">${stamp(r.at)}<span class="dot"></span></div><div class="row-body"><details data-record="${i}"><summary class="record-summary"><strong>${esc(r.verdict)}</strong><code>${esc(r.key||r.entry_id||r.entry?.id)}</code><span>${esc(r.kind==='miss'?'Demand':r.kind)}</span></summary><div class="record-expand"></div></details></div></div>`).join(''):'<div class="row"><div class="stamp"></div><div class="row-body">No requests here. Run a lookup or a check.</div></div>';document.querySelectorAll('[data-record]').forEach(el=>el.addEventListener('toggle',async()=>{if(!el.open||el.dataset.loaded)return;const r=rows[+el.dataset.record];try{r.entry=r.entry||await manifest(r.entry_id);r.reason=r.reason||(r.kind==='miss'?'No match. Logged as demand. Try another specification.':'Earlier service response. Expand the package to re-check its proof.');el.querySelector('.record-expand').innerHTML=expanded(r);el.dataset.loaded='true';}catch(e){el.querySelector('.record-expand').textContent=e.message;}}));}
function record(r){if(current&&current.kind!=='selected')local.unshift(current);current={...r,at:new Date().toISOString()};renderCurrent();renderHistory();}
async function lookup(){const key=$('#query').value.trim();if(!key){$('#connection').textContent='Enter a specification, then select Look up.';return;}const r=await api('lookup',{spec_id:key});if(r.ok){const id=r.data.entry_id||r.data.entry?.id||r.data.id;const e=await manifest(id);record({kind:'lookup',key,entry:e,verdict:'Found',reason:'Match found. The lit path connects the entry to its delivered evidence.',metrics:`HTTP ${r.status} / re-check the package before trusting the result`,result:r.data});}else record({kind:r.status===404?'miss':'lookup',key,verdict:r.status===404?'No match':'Error',reason:r.status===404?'Logged as demand. Try another specification or read the demand log.':r.data.detail,metrics:`HTTP ${r.status}`,result:r.data});await loadLogs();}
async function check(){let input;try{input=JSON.parse($('#input').value);}catch{record({kind:'check',entry:selected,verdict:'Input error',reason:'The input is not valid JSON. Correct it and run the check again.'});return;}if(!selected){$('#connection').textContent='Select a library entry before running a check.';return;}const r=await api('checks/'+encodeURIComponent(selected.id),input);record({kind:'check',entry:selected,key:selected.id,verdict:r.ok?r.data.verdict:r.status===409?'No checker':'Error',reason:r.ok?(r.data.output?.reason||'Read the checker response and re-check locally.'):r.status===409?'This entry has no runnable checker. Select a checker entry.':r.data.detail,metrics:r.ok?`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code} / HTTP ${r.status}`:`HTTP ${r.status}`,result:r.data});await loadLogs();}
function failure(e){$('#connection').textContent='The request could not complete. Check the connection and try again. '+e.message;document.body.dataset.ready='error';}
$('#lookup').onsubmit=e=>{e.preventDefault();lookup().catch(failure);};$('#run').onclick=()=>check().catch(failure);$('#example').onclick=()=>{if(selected?.check){$('#input').value=JSON.stringify(selected.check.example_input,null,2);$('#input-note').textContent='Example loaded. Edit the JSON or run the check.';}else $('#input-note').textContent='Select a checker entry to load an example.';};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.entry)await select(b.dataset.entry);if(b.dataset.filter){filter=b.dataset.filter;renderHistory();}if(b.dataset.copy){await navigator.clipboard.writeText(cache.get(b.dataset.copy).replay.command);b.textContent='Command copied';}}catch(err){if(b.dataset.copy)b.textContent='Select and copy the command above';else failure(err);}});
async function init(){const r=await api('catalog');if(!r.ok)throw new Error(r.data.detail);entries=r.data.entries;let checker=null;for(const e of [...entries.filter(e=>e.kind==='checker'),...entries.filter(e=>e.kind!=='checker')]){const full=await manifest(e.id);if(full?.check){checker=full;break;}}const state=new URLSearchParams(location.search).get('state')||location.hash.slice(1)||'catalog';const recorded=entries.find(e=>e.replay_status==='recorded');await select((['recorded','check-409'].includes(state)?recorded?.id:checker?.id)||entries[0].id,['entry','recorded'].includes(state));await loadLogs();if(state==='lookup-hit'||state==='lookup-miss'){$('#query').value=state==='lookup-hit'?checker.id:'unmatched.example';await lookup();}if(['check-accept','check-reject','check-409'].includes(state)){if(state==='check-reject'){const input=JSON.parse($('#input').value);input.rows[0].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2);}await check();}if(state==='demand'||state==='answers'){filter=state;renderHistory();$('#history').scrollIntoView({block:'start'});}document.body.dataset.ready='true';}
init().catch(failure);
